def check_if_last_char_is_a_letter(txt):
    import re
    if not txt:
        return False
    words = re.split(r'\s+', txt)
    if not words:
        return False
    last_word = words[-1]
    if not last_word:
        return False
    if not last_word[-1].isalpha():
        return False
    return True
